insert into programas (slug,titulo,subtitulo,capa_url,ordem,ativo) values ('mobilidade','Mobilidade','5 rotinas · 8 min','icons/mobilidade_s.jpg',3,true)
insert into programa_treinos (programa_id,nome,duracao_min,ordem,exercicios) values ((select id from programas where slug='mobilidade'),'Quadril e lombar',8,1,'[{"nome": "Mobilidade de quadril", "series": 2, "reps": "12 cada lado", "descanso_s": 0}, {"nome": "Gato-camelo", "series": 2, "reps": "10", "descanso_s": 0, "dica": "Arredonda as costas soltando o ar e depois afunda devagar, sem pressa"}, {"nome": "Mobilidade 90/90 de quadril", "series": 2, "reps": "8 cada lado", "descanso_s": 0, "dica": "Sentada no chão, gira os joelhos de um lado pro outro sem tirar o bumbum do chão"}, {"nome": "Alongamento do piriforme deitada", "series": 2, "reps": "30s cada lado", "descanso_s": 0, "dica": "Puxa o joelho na direção do ombro do outro lado e segura"}, {"nome": "Ponte isométrica", "series": 2, "reps": "30s", "descanso_s": 15}]'::jsonb);
insert into programa_treinos (programa_id,nome,duracao_min,ordem,exercicios) values ((select id from programas where slug='mobilidade'),'Posterior e lombar',8,2,'[{"nome": "Alongamento de Posteriores", "series": 3, "reps": "15s cada lado", "descanso_s": 0}, {"nome": "Good morning sem carga", "series": 2, "reps": "12", "descanso_s": 15, "dica": "Leva o quadril pra trás com as costas retas, sem peso nenhum"}, {"nome": "Alongamento de flexor de quadril ajoelhada", "series": 2, "reps": "30s cada lado", "descanso_s": 0, "dica": "Ajoelhada, contrai o bumbum e leva o quadril pra frente devagar"}, {"nome": "Dead Bug", "series": 2, "reps": "10 cada lado", "descanso_s": 15}]'::jsonb);
insert into programa_treinos (programa_id,nome,duracao_min,ordem,exercicios) values ((select id from programas where slug='mobilidade'),'Ombro e coluna',8,3,'[{"nome": "Rotação torácica em quatro apoios", "series": 2, "reps": "8 cada lado", "descanso_s": 0, "dica": "Mão atrás da cabeça, abre o cotovelo pro teto seguindo com o olhar"}, {"nome": "Livro aberto deitada de lado", "series": 2, "reps": "8 cada lado", "descanso_s": 0, "dica": "Joelhos juntos no chão, abre o braço de cima até o outro lado"}, {"nome": "Deslizamento na parede (wall slide)", "series": 2, "reps": "10", "descanso_s": 0, "dica": "Costas e braços colados na parede, sobe e desce os braços devagar"}, {"nome": "Alongamento de peitoral na parede", "series": 2, "reps": "30s cada lado", "descanso_s": 0, "dica": "Antebraço apoiado na parede, gira o corpo pro lado contrário"}]'::jsonb);
insert into programa_treinos (programa_id,nome,duracao_min,ordem,exercicios) values ((select id from programas where slug='mobilidade'),'Tornozelo e joelho',8,4,'[{"nome": "Mobilidade de tornozelo na parede", "series": 2, "reps": "10 cada lado", "descanso_s": 0, "dica": "Pé perto da parede, leva o joelho pra frente sem tirar o calcanhar do chão"}, {"nome": "Agachamento Cossaco (mobilidade)", "series": 2, "reps": "6 cada lado", "descanso_s": 0}, {"nome": "Agachamento Lateral Alternado", "series": 2, "reps": "8 cada lado", "descanso_s": 15}, {"nome": "Agachamento profundo com pausa", "series": 2, "reps": "30s", "descanso_s": 15, "dica": "Desce o máximo que der com o calcanhar no chão e fica lá respirando"}]'::jsonb);
