-- Migração 025 (17/11/2026): treinos dos programas extras (Mobilidade, Abdômen, Casa, Corrida) + programa novo HIIT
-- Aprovado pelo Igor em 17/11. Reexecutável: apaga e recria só os treinos desses 5 programas.
begin;
  on conflict (slug) do update set titulo=excluded.titulo, subtitulo=excluded.subtitulo, capa_url=excluded.capa_url, ordem=excluded.ordem, ativo=true;
delete from programa_treinos where programa_id=(select id from programas where slug='mobilidade');
  on conflict (slug) do update set titulo=excluded.titulo, subtitulo=excluded.subtitulo, capa_url=excluded.capa_url, ordem=excluded.ordem, ativo=true;
delete from programa_treinos where programa_id=(select id from programas where slug='abdomen');
  on conflict (slug) do update set titulo=excluded.titulo, subtitulo=excluded.subtitulo, capa_url=excluded.capa_url, ordem=excluded.ordem, ativo=true;
delete from programa_treinos where programa_id=(select id from programas where slug='casa');
  on conflict (slug) do update set titulo=excluded.titulo, subtitulo=excluded.subtitulo, capa_url=excluded.capa_url, ordem=excluded.ordem, ativo=true;
delete from programa_treinos where programa_id=(select id from programas where slug='corrida');
  on conflict (slug) do update set titulo=excluded.titulo, subtitulo=excluded.subtitulo, capa_url=excluded.capa_url, ordem=excluded.ordem, ativo=true;
delete from programa_treinos where programa_id=(select id from programas where slug='hiit');
commit;
select p.slug, count(t.id) treinos from programas p left join programa_treinos t on t.programa_id=p.id group by p.slug order by 1;
